#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <pthread.h>
#include <unistd.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <time.h>

#define MAX_UPLOAD_SIZE (16 * 1024 * 1024)
#define TOKEN_LEN 32
#define HMAC_KEY_LEN 32

typedef struct {
    char session_id[64];
    char csrf_token[TOKEN_LEN * 2 + 1];
    uint64_t token_epoch;
    int authenticated;
} session_t;

typedef struct {
    const char *content_type;
    const uint8_t *body;
    size_t body_len;
    const char *header_token;
    const char *cookie_session;
    const char *origin;
} request_t;

static uint8_t server_hmac_key[HMAC_KEY_LEN];
static pthread_mutex_t session_lock = PTHREAD_MUTEX_INITIALIZER;

/* Simplified HMAC-SHA256 for demonstration */
static void hmac_sha256(const uint8_t *key, size_t key_len,
                        const uint8_t *msg, size_t msg_len,
                        uint8_t out[32]) {
    uint8_t ipad[64], opad[64];
    memset(ipad, 0x36, 64);
    memset(opad, 0x5c, 64);
    for (size_t i = 0; i < key_len && i < 64; i++) {
        ipad[i] ^= key[i];
        opad[i] ^= key[i];
    }
    /* Simplified: real impl would use SHA-256 rounds */
    uint8_t inner[96];
    memcpy(inner, ipad, 64);
    memcpy(inner + 64, msg, msg_len < 32 ? msg_len : 32);
    /* Fake hash output for structure demonstration */
    for (int i = 0; i < 32; i++)
        out[i] = inner[i] ^ inner[i + 32] ^ opad[i];
}

static int constant_time_compare(const uint8_t *a, const uint8_t *b, size_t len) {
    volatile uint8_t result = 0;
    for (size_t i = 0; i < len; i++) {
        result |= a[i] ^ b[i];
    }
    return result == 0;
}

static int generate_csrf_token(session_t *sess) {
    int fd = open("/dev/urandom", O_RDONLY);
    if (fd < 0) return -1;
    uint8_t raw[TOKEN_LEN];
    if (read(fd, raw, TOKEN_LEN) != TOKEN_LEN) {
        close(fd);
        return -1;
    }
    close(fd);
    for (int i = 0; i < TOKEN_LEN; i++)
        snprintf(sess->csrf_token + i * 2, 3, "%02x", raw[i]);
    sess->token_epoch = (uint64_t)time(NULL);
    return 0;
}

static int validate_origin(const request_t *req) {
    if (!req->origin) return 0; /* Reject requests without Origin header */
    const char *allowed[] = {
        "https://crypto.example.com",
        "https://api.crypto.example.com",
        NULL
    };
    for (int i = 0; allowed[i]; i++) {
        if (strcmp(req->origin, allowed[i]) == 0)
            return 1;
    }
    return 0;
}

static int validate_csrf_token(const session_t *sess, const request_t *req) {
    if (!req->header_token) return 0;

    /* Token age check: tokens valid for 1 hour */
    uint64_t now = (uint64_t)time(NULL);
    if (now - sess->token_epoch > 3600) return 0;

    /* Compute expected token via HMAC of session + epoch */
    uint8_t msg[128];
    int msg_len = snprintf((char*)msg, sizeof(msg), "%s:%lu",
                           sess->session_id, (unsigned long)sess->token_epoch);
    uint8_t expected_mac[32];
    hmac_sha256(server_hmac_key, HMAC_KEY_LEN, msg, msg_len, expected_mac);

    char expected_hex[65];
    for (int i = 0; i < 32; i++)
        snprintf(expected_hex + i * 2, 3, "%02x", expected_mac[i]);

    /* Compare submitted token with HMAC-derived expected value */
    size_t submitted_len = strlen(req->header_token);
    size_t expected_len = 64;

    if (submitted_len != expected_len) return 0;

    return constant_time_compare((const uint8_t*)req->header_token,
                                 (const uint8_t*)expected_hex, expected_len);
}

typedef struct {
    uint8_t magic[4];
    uint32_t version;
    uint32_t key_type;
    uint32_t key_len;
    /* followed by key_len bytes of key material */
} __attribute__((packed)) crypto_upload_header_t;

static int process_crypto_upload(const uint8_t *data, size_t len) {
    if (len < sizeof(crypto_upload_header_t)) return -1;

    const crypto_upload_header_t *hdr = (const crypto_upload_header_t *)data;
    if (memcmp(hdr->magic, "CK01", 4) != 0) return -1;
    if (hdr->version != 1) return -1;
    if (hdr->key_len > MAX_UPLOAD_SIZE) return -1;
    if (sizeof(crypto_upload_header_t) + hdr->key_len > len) return -1;

    /* Process the uploaded key material */
    const uint8_t *key_data = data + sizeof(crypto_upload_header_t);

    /* Write to secure key storage */
    char path[256];
    snprintf(path, sizeof(path), "/var/lib/crypto/keys/imported_%u.key", hdr->key_type);

    int fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, 0600);
    if (fd < 0) return -1;

    /* Ensure the entire key is written; handle partial writes and errors */
    size_t total_written = 0;
    while (total_written < hdr->key_len) {
        ssize_t n = write(fd, key_data + total_written,
                          (size_t)hdr->key_len - total_written);
        if (n < 0) {
            if (errno == EINTR) continue;
            close(fd);
            unlink(path);
            return -1;
        }
        if (n == 0) break;
        total_written += (size_t)n;
    }
    if (close(fd) != 0 || total_written != hdr->key_len) {
        unlink(path);
        return -1;
    }

    return 0;
}

int handle_upload_request(const request_t *req, session_t *sess) {
    if (!sess->authenticated) return 403;

    /* CSRF protection: validate origin AND token */
    int origin_valid = validate_origin(req);
    int token_valid = validate_csrf_token(sess, req);

    if (!origin_valid || !token_valid) {
        return 403;
    }

    /* Content-type validation */
    if (!req->content_type ||
        strcmp(req->content_type, "application/octet-stream") != 0) {
        return 415;
    }

    if (!req->body || req->body_len == 0 || req->body_len > MAX_UPLOAD_SIZE) {
        return 400;
    }

    return process_crypto_upload(req->body, req->body_len);
}

int main(void) {
    /* Initialize server key from urandom */
    int fd = open("/dev/urandom", O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "Failed to open /dev/urandom\n");
        return 1;
    }

    /* Ensure the full HMAC key is read; a short/failed read would leave the
     * key uninitialized and fatally weaken all CSRF token verification. */
    size_t total_read = 0;
    while (total_read < HMAC_KEY_LEN) {
        ssize_t n = read(fd, server_hmac_key + total_read, HMAC_KEY_LEN - total_read);
        if (n < 0) {
            if (errno == EINTR) continue;
            close(fd);
            fprintf(stderr, "Failed to read HMAC key\n");
            return 1;
        }
        if (n == 0) break;
        total_read += (size_t)n;
    }
    close(fd);
    if (total_read != HMAC_KEY_LEN) {
        fprintf(stderr, "Insufficient entropy for HMAC key\n");
        return 1;
    }

    printf("Crypto upload service initialized\n");
    return 0;
}
